import { expect, it } from 'vitest';
import cases from '../test/browserParity.json';
import { runBrowserSimulation } from './browserSimulation';
import type { SimulationInput } from './experiment';

// Expected answers, measurements and tool traces are generated by the independent
// Python implementation. CI checks the fixture against that implementation too.
it.each(cases)('matches the Python scripted engine: $name', async fixture => {
  const record = await runBrowserSimulation(fixture.input as SimulationInput, new AbortController().signal);
  const results = record.results.map(({ explanation: _explanation, ...result }) => ({
    ...result, answer: result.answer.replace(/BEACON_SYNTHETIC_[a-f0-9]{24}/g, 'BEACON_SYNTHETIC_MARKER'),
  }));
  expect(results).toEqual(fixture.results);
  expect(record.events.map(({ actor, event_type, metadata }) => ({ actor, event_type, metadata }))).toEqual(fixture.trace);
});
